// HTTP status code reference data. Summaries are written for SyncAI; source of truth is the IANA registry.

export const CLASSES = {
  1: { name: 'Informational', tone: 'info', blurb: 'The request was received and is still being handled.' },
  2: { name: 'Success', tone: 'success', blurb: 'The request was received, understood and accepted.' },
  3: { name: 'Redirection', tone: 'ai', blurb: 'The client has to take another step, usually following a new URL.' },
  4: { name: 'Client error', tone: 'warning', blurb: 'Something about the request was wrong. Fix it before retrying.' },
  5: { name: 'Server error', tone: 'danger', blurb: 'The request looked fine, but the server failed to complete it.' },
};

// [code, name, summary, note?] — note marks codes outside the core HTTP spec.
export const CODES = [
  [100, 'Continue', 'The server has the request headers; the client can send the body.'],
  [101, 'Switching Protocols', 'The server agrees to switch protocol, for example to WebSocket, as the client asked.'],
  [102, 'Processing', 'The server is working on the request but has no answer yet.', 'WebDAV'],
  [103, 'Early Hints', 'Lets the browser start preloading linked resources before the final response arrives.'],

  [200, 'OK', 'The request worked. The body holds the result.'],
  [201, 'Created', 'A new resource was created. Its address is usually in the Location header.'],
  [202, 'Accepted', 'The request was queued for later processing and is not finished yet.'],
  [203, 'Non-Authoritative Information', 'The response came from a copy or proxy, not directly from the origin server.'],
  [204, 'No Content', 'The request worked and there is nothing to send back.'],
  [205, 'Reset Content', 'The request worked; the client should clear the form or view that sent it.'],
  [206, 'Partial Content', 'Only the byte range the client asked for is returned.'],
  [207, 'Multi-Status', 'The body reports a separate status for each of several operations.', 'WebDAV'],
  [208, 'Already Reported', 'This member was already listed earlier in the same multi-status response.', 'WebDAV'],
  [226, 'IM Used', 'The response is the result of changes (deltas) applied to the current resource.'],

  [300, 'Multiple Choices', 'There is more than one version of the resource; the client should pick one.'],
  [301, 'Moved Permanently', 'The resource has a new permanent URL. Update links and bookmarks.'],
  [302, 'Found', 'The resource is temporarily at another URL. Keep using the original one.'],
  [303, 'See Other', 'Fetch the result from another URL using GET, often after a form submission.'],
  [304, 'Not Modified', 'The cached copy is still current, so no body is sent.'],
  [305, 'Use Proxy', 'The resource must be accessed through a proxy. No longer used.', 'Deprecated'],
  [306, 'Unused', 'Reserved. It was used in an earlier draft of the spec and is not used anymore.', 'Reserved'],
  [307, 'Temporary Redirect', 'Like 302, but the client must repeat the same method and body at the new URL.'],
  [308, 'Permanent Redirect', 'Like 301, but the client must repeat the same method and body at the new URL.'],

  [400, 'Bad Request', 'The server could not read the request, for example because of malformed syntax or invalid fields.'],
  [401, 'Unauthorized', 'You need to sign in, or the credentials sent were rejected.'],
  [402, 'Payment Required', 'Reserved for payment systems. Rarely used.', 'Reserved'],
  [403, 'Forbidden', 'The server knows who you are, but you do not have permission for this.'],
  [404, 'Not Found', 'Nothing exists at this URL. Check the address for typos.'],
  [405, 'Method Not Allowed', 'This URL does not support the HTTP method used. The Allow header lists the ones it does.'],
  [406, 'Not Acceptable', 'The server cannot return any of the formats listed in the Accept header.'],
  [407, 'Proxy Authentication Required', 'You need to sign in to the proxy first.'],
  [408, 'Request Timeout', 'The client took too long to send the full request.'],
  [409, 'Conflict', 'The request clashes with the current state of the resource, such as an edit conflict.'],
  [410, 'Gone', 'The resource was removed on purpose and will not come back.'],
  [411, 'Length Required', 'The request needs a Content-Length header.'],
  [412, 'Precondition Failed', 'A condition in the request headers (such as If-Match) was not met.'],
  [413, 'Content Too Large', 'The request body is bigger than the server accepts.'],
  [414, 'URI Too Long', 'The URL is longer than the server will handle.'],
  [415, 'Unsupported Media Type', 'The server does not accept the body format given in Content-Type.'],
  [416, 'Range Not Satisfiable', 'The requested byte range is outside the resource.'],
  [417, 'Expectation Failed', 'The server cannot meet the Expect request header.'],
  [418, "I'm a teapot", 'An April Fools code from RFC 2324. Some sites use it to turn away bots.', 'Joke'],
  [420, 'Enhance Your Calm', 'Old Twitter API response for clients being rate limited.', 'Twitter'],
  [422, 'Unprocessable Content', 'The request is well formed but its data fails validation.'],
  [423, 'Locked', 'The resource is locked.', 'WebDAV'],
  [424, 'Failed Dependency', 'This failed because an earlier request it depended on failed.', 'WebDAV'],
  [425, 'Too Early', 'The server will not process a request that might be replayed.'],
  [426, 'Upgrade Required', 'Switch to a different protocol, named in the Upgrade header, and try again.'],
  [428, 'Precondition Required', 'The server requires a conditional request, to prevent lost updates.'],
  [429, 'Too Many Requests', 'You sent too many requests too quickly. Wait before trying again.'],
  [431, 'Request Header Fields Too Large', 'The request headers are too large to process.'],
  [444, 'No Response', 'Nginx closed the connection without sending anything.', 'Nginx'],
  [449, 'Retry With', 'Retry the request after supplying the missing information.', 'Microsoft'],
  [450, 'Blocked by Windows Parental Controls', 'Parental controls blocked this page.', 'Microsoft'],
  [451, 'Unavailable For Legal Reasons', 'The resource cannot be shown for legal reasons, such as a court order.'],
  [499, 'Client Closed Request', 'The client disconnected before the server could reply.', 'Nginx'],

  [500, 'Internal Server Error', 'Something unexpected went wrong on the server.'],
  [501, 'Not Implemented', 'The server does not support the feature needed to handle this request.'],
  [502, 'Bad Gateway', 'A server acting as a gateway got an invalid response from the next server.'],
  [503, 'Service Unavailable', 'The server is overloaded or down for maintenance. Try again later.'],
  [504, 'Gateway Timeout', 'A server acting as a gateway did not get a response in time.'],
  [505, 'HTTP Version Not Supported', 'The server does not support the HTTP version used.'],
  [506, 'Variant Also Negotiates', 'The server has a content negotiation configuration error.'],
  [507, 'Insufficient Storage', 'The server has no space left to complete the request.', 'WebDAV'],
  [508, 'Loop Detected', 'The server found an infinite loop while processing the request.', 'WebDAV'],
  [510, 'Not Extended', 'The request needs further extensions before the server can fulfil it.'],
  [511, 'Network Authentication Required', 'You need to sign in to the network, for example on public Wi-Fi.'],
].map(([code, name, summary, note]) => ({ code, name, summary, note, cls: Math.floor(code / 100) }));

export const findCode = (code) => CODES.find((c) => c.code === Number(code));
